            /// <summary>
            /// Global <c>Element</c> keys, defined for all tags regardless of their namespace.
            /// <br /><br />
            /// That's <c>keys</c> that are defined BY ALL <c>HTMLElement/SVGElement/MathMLElement</c> interfaces.
            /// <br /><br />
            /// Includes <c>keys</c> defined for the <c>Element</c> and <c>Node</c> interfaces.
            /// </summary>
            type DOMAttributes<'T> =
                inherit CustomAttributes<'T>
                inherit CustomEventHandlersCamelCase<'T>
                inherit CustomEventHandlersLowerCase<'T>
                inherit CustomEventHandlersNamespaced<'T>
                inherit AriaAttributes
                abstract innerHTML: U2<string, (unit -> string)> option with get, set
                abstract textContent: U3<string, float, (unit -> U2<string, float>)> option with get, set
                abstract autofocus: U2<bool, (unit -> bool option)> option with get, set
                abstract ``class``: U2<string, (unit -> string option)> option with get, set
                abstract elementtiming: U2<string, (unit -> string option)> option with get, set
                abstract id: U2<string, (unit -> string option)> option with get, set
                abstract nonce: U2<string, (unit -> string option)> option with get, set
                abstract slot: U2<string, (unit -> string option)> option with get, set
                abstract style: U3<string, CSSProperties, (unit -> U2<string, CSSProperties> option)> option with get, set
                abstract tabindex: U3<string, float, (unit -> U2<string, float> option)> option with get, set
                abstract tabIndex: U3<string, float, (unit -> U2<string, float> option)> option with get, set

            type CSSProperties =
                /// <summary>
                /// This feature is not Baseline because it does not work in some of the most widely-used browsers.
                /// <br /><br />
                /// <b>Syntax</b>: <c>auto | &lt;color&gt;</c>
                /// <br /><br />
                /// <b>Initial value</b>: <c>auto</c>
                /// <br /><br />
                /// | Chrome | Firefox |  Safari  |  Edge  | IE  |
                /// | :----: | :-----: | :------: | :----: | :-: |
                /// | <b>93</b> | <b>92</b>  | <b>15.4</b> | <b>93</b> | No  |
                /// </summary>
                /// <remarks>@see https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/accent-color</remarks>
                abstract ``accent-color``: string option with get, set
                /// <summary>
                /// This feature is well established and works across many devices and browser versions. It’s been available across browsers since September 2015.
                /// <br /><br />
                /// <b>Syntax</b>: <c>normal | &lt;baseline-position&gt; | &lt;content-distribution&gt; | &lt;overflow-position&gt;? &lt;content-position&gt;</c>
                /// <br /><br />
                /// <b>Initial value</b>: <c>normal</c>
                /// <br /><br />
                /// |  Chrome  | Firefox | Safari  |  Edge  |   IE   |
                /// | :------: | :-----: | :-----: | :----: | :----: |
                /// |  <b>29</b>  | <b>28</b>  |  <b>9</b>  | <b>12</b> | <b>11</b> |
                /// | 21 _-x-_ |         | 7 _-x-_ |        |        |
                /// </summary>
                /// <remarks>@see https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/align-content</remarks>
                abstract ``align-content``: string option with get, set
                /// <summary>
                /// This feature is well established and works across many devices and browser versions. It’s been available across browsers since September 2015.
                /// <br /><br />
                /// <b>Syntax</b>: <c>normal | stretch | &lt;baseline-position&gt; | [ &lt;overflow-position&gt;? &lt;self-position&gt; ] | anchor-center</c>
                /// <br /><br />
                /// <b>Initial value</b>: <c>normal</c>
                /// <br /><br />
                /// |  Chrome  | Firefox | Safari  |  Edge  |   IE   |
                /// | :------: | :-----: | :-----: | :----: | :----: |
                /// |  <b>29</b>  | <b>20</b>  |  <b>9</b>  | <b>12</b> | <b>11</b> |
                /// | 21 _-x-_ |         | 7 _-x-_ |        |        |
                /// </summary>
                /// <remarks>@see https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/align-items</remarks>
                abstract ``align-items``: string option with get, set
                /// <summary>
                /// This feature is well established and works across many devices and browser versions. It’s been available across browsers since September 2015.
                /// <br /><br />
                /// <b>Syntax</b>: <c>auto | normal | stretch | &lt;baseline-position&gt; | &lt;overflow-position&gt;? &lt;self-position&gt; | anchor-center</c>
                /// <br /><br />
                /// <b>Initial value</b>: <c>auto</c>
                /// <br /><br />
